import { test, expect } from '@playwright/test';

test.describe('Search Results - Highlighted Search Terms', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.google.com');
  });

  test('should highlight search terms in result snippets', async ({ page }) => {
    // Perform a search
    const searchBox = page.getByRole('combobox', { name: /search/i });
    await searchBox.fill('playwright testing');
    await page.keyboard.press('Enter');

    // Wait for results to load
    await page.waitForLoadState('networkidle');

    // Get the first search result snippet
    const firstResult = page.locator('div[data-sokoban-container]').first();
    await expect(firstResult).toBeVisible();

    // Check that the snippet contains the search terms
    const snippet = firstResult.locator('span').first();
    const snippetText = await snippet.textContent();

    expect(snippetText).toContain('playwright');
    expect(snippetText).toContain('testing');

    // Verify that highlighted terms have specific styling (typically bold or different color)
    const highlightedElements = firstResult.locator('b');
    const highlightCount = await highlightedElements.count();

    expect(highlightCount).toBeGreaterThan(0);

    // Verify each highlighted element contains part of the search terms
    for (let i = 0; i < highlightCount; i++) {
      const highlightedText = await highlightedElements.nth(i).textContent();
      const lowerText = highlightedText?.toLowerCase() || '';
      const isSearchTerm = 'playwright'.includes(lowerText) || 'testing'.includes(lowerText) || 
                          lowerText.includes('playwright') || lowerText.includes('testing');
      expect(isSearchTerm).toBeTruthy();
    }
  });

  test('should highlight multiple occurrences of search terms in snippets', async ({ page }) => {
    // Perform a search with a common term
    const searchBox = page.getByRole('combobox', { name: /search/i });
    await searchBox.fill('javascript');
    await page.keyboard.press('Enter');

    // Wait for results to load
    await page.waitForLoadState('networkidle');

    // Check multiple results for highlighting
    const results = page.locator('div[data-sokoban-container]');
    const resultCount = await results.count();

    expect(resultCount).toBeGreaterThan(0);

    // Verify at least 3 results have highlighted terms
    let resultsWithHighlights = 0;
    const maxResults = Math.min(5, resultCount);

    for (let i = 0; i < maxResults; i++) {
      const result = results.nth(i);
      const highlightedElements = result.locator('b');
      const highlightCount = await highlightedElements.count();

      if (highlightCount > 0) {
        resultsWithHighlights++;
      }
    }

    expect(resultsWithHighlights).toBeGreaterThanOrEqual(1);
  });

  test('should maintain highlight consistency across different search terms', async ({ page }) => {
    // First search
    const searchBox = page.getByRole('combobox', { name: /search/i });
    await searchBox.fill('automation testing');
    await page.keyboard.press('Enter');

    await page.waitForLoadState('networkidle');

    // Get highlights from first search
    const firstSearchHighlights = page.locator('div[data-sokoban-container] b');
    const firstSearchHighlightCount = await firstSearchHighlights.count();

    expect(firstSearchHighlightCount).toBeGreaterThan(0);

    // Clear and perform second search
    await searchBox.click();
    await searchBox.triple_click();
    await searchBox.fill('quality assurance');
    await page.keyboard.press('Enter');

    await page.waitForLoadState('networkidle');

    // Get highlights from second search
    const secondSearchHighlights = page.locator('div[data-sokoban-container] b');
    const secondSearchHighlightCount = await secondSearchHighlights.count();

    expect(secondSearchHighlightCount).toBeGreaterThan(0);

    // Verify that highlights are present in both searches
    expect(firstSearchHighlightCount).toBeGreaterThan(0);
    expect(secondSearchHighlightCount).toBeGreaterThan(0);
  });

  test('should display highlighted terms with proper visual distinction', async ({ page }) => {
    // Perform a search
    const searchBox = page.getByRole('combobox', { name: /search/i });
    await searchBox.fill('web development');
    await page.keyboard.press('Enter');

    await page.waitForLoadState('networkidle');

    // Get the first result
    const firstResult = page.locator('div[data-sokoban-container]').first();

    // Find highlighted elements
    const highlightedTerms = firstResult.locator('b');
    const highlightCount = await highlightedTerms.count();

    expect(highlightCount).toBeGreaterThan(0);

    // Verify visual properties of highlighted elements
    for (let i = 0; i < Math.min(highlightCount, 3); i++) {
      const highlightedElement = highlightedTerms.nth(i);

      // Check that the element is visible
      await expect(highlightedElement).toBeVisible();

      // Verify the element has text content
      const text = await highlightedElement.textContent();
      expect(text).toBeTruthy();
      expect(text?.length).toBeGreaterThan(0);
    }
  });

  test('should handle special characters in search terms with proper highlighting', async ({ page }) => {
    // Perform a search with special characters
    const searchBox = page.getByRole('combobox', { name: /search/i });
    await searchBox.fill('c++ programming');
    await page.keyboard.press('Enter');

    await page.waitForLoadState('networkidle');

    // Verify results are displayed
    const results = page.locator('div[data-sokoban-container]');
    const resultCount = await results.count();

    expect(resultCount).toBeGreaterThan(0);

    // Check for highlighted elements in results
    const highlightedElements = page.locator('div[data-sokoban-container] b');
    const highlightCount = await highlightedElements.count();

    // Should have at least some highlights even with special characters
    expect(highlightCount).toBeGreaterThanOrEqual(0);
  });
});
